```js
const DEFAULTS = { retries: 2, timeoutMs: 5000, headers: {} };

export function createClient(baseUrl, options = {}) {
  const cfg = { ...DEFAULTS, ...options };
  const listeners = { request: [], response: [], error: [] };

  async function request(method, path, body) {
    const url = baseUrl.replace(/\/$/, '') + path;
    listeners.request.forEach((fn) => fn({ method, url }));
    let lastErr;
    for (let i = 0; i <= cfg.retries; i++) {
      try {
        const res = await fetch(url, {
          method,
          headers: { 'Content-Type': 'application/json', ...cfg.headers },
          body: body === undefined ? undefined : JSON.stringify(body),
          signal: AbortSignal.timeout(cfg.timeoutMs),
        });
        const data = res.status === 204 ? null : await res.json();
        listeners.response.forEach((fn) => fn({ status: res.status, data }));
        if (!res.ok) throw Object.assign(new Error('HTTP ' + res.status), { status: res.status, data });
        return data;
      } catch (e) {
        lastErr = e;
        if (e.status && e.status < 500) break;
      }
    }
    listeners.error.forEach((fn) => fn(lastErr));
    throw lastErr;
  }

  return {
    get: (p) => request('GET', p),
    post: (p, b) => request('POST', p, b),
    on: (evt, fn) => listeners[evt].push(fn),
  };
}
