Refactor this C# so adding a new shipping method doesn't mean editing this method.

```csharp
public decimal CalculateShipping(Order order, string method)
{
    decimal cost;
    switch (method)
    {
        case "standard":
            cost = 5.00m + 0.50m * order.WeightKg;
            if (order.Subtotal > 100) cost = 0;
            break;
        case "express":
            cost = 12.00m + 0.90m * order.WeightKg;
            if (order.Destination.IsRemote) cost += 8.00m;
            break;
        case "pickup":
            cost = 0;
            break;
        case "freight":
            if (order.WeightKg < 30) throw new InvalidOperationException("Freight needs 30kg minimum");
            cost = 45.00m + 0.35m * order.WeightKg;
            break;
        default:
            throw new ArgumentException("Unknown method " + method);
    }
    return Math.Round(cost, 2);
}
